     1→/**
     2→ * Public API endpoint for the storefront zip code widget.
     3→ *
     4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
     5→ * to check whether a zip code is serviceable.
     6→ *
     7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
     8→ *
     9→ * Response:
    10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
    11→ *   200 { allowed: false, message: "..." }
    12→ *   400 { error: "Missing shop or zip parameter" }
    13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
    14→ */
    15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
    16→import db from "../db.server";
    17→
    18→const CORS_HEADERS = {
    19→  "Access-Control-Allow-Origin": "*",
    20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    21→  "Access-Control-Allow-Headers": "Content-Type",
    22→  "Content-Type": "application/json",
    23→};
    24→
    25→// Applied only to successful ZIP check responses (200) to reduce DB load
    26→// for repeated lookups of the same ZIP code from the same storefront visitor.
    27→const SUCCESS_HEADERS = {
    28→  ...CORS_HEADERS,
    29→  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
    30→};
    31→
    32→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
    33→
    34→async function handleZipCheck(shop: string | null, zip: string | null) {
    35→  if (!shop || !zip) {
    36→    return new Response(
    37→      JSON.stringify({ error: "Missing shop or zip parameter" }),
    38→      { status: 400, headers: CORS_HEADERS },
    39→    );
    40→  }
    41→
    42→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
    43→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
    44→    return new Response(
    45→      JSON.stringify({ error: "Invalid shop parameter" }),
    46→      { status: 400, headers: CORS_HEADERS },
    47→    );
    48→  }
    49→
    50→  // Enforce input length limits to prevent abuse
    51→  if (zip.length > 20) {
    52→    return new Response(
    53→      JSON.stringify({ error: "Invalid zip code" }),
    54→      { status: 400, headers: CORS_HEADERS },
    55→    );
    56→  }
    57→
    58→  const normalizedZip = zip.trim().toUpperCase();
    59→
    60→  const zipRecord = await db.zipCode.findUnique({
    61→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
    62→  });
    63→
    64→  // Fetch widget config for custom messages (falls back to defaults)
    65→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
    66→
    67→  // Fetch shop settings to determine default behavior for unlisted zip codes
    68→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
    69→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
    70→
    71→  if (!zipRecord || !zipRecord.isActive) {
    72→    const notFoundMsg =
    73→      widgetConfig?.notFoundMessage ??
    74→      "This zip code was not found in our system.";
    75→
    76→    // If the zip is simply not in the list (not inactive) and the merchant
    77→    // has set defaultBehavior to "allow", treat it as an allowed zip
    78→    if (!zipRecord && defaultBehavior === "allow") {
    79→      const successMsg =
    80→        widgetConfig?.successMessage ?? "We deliver to your area!";
    81→      return new Response(
    82→        JSON.stringify({
    83→          allowed: true,
    84→          message: successMsg,
    85→          eta: null,
    86→          zone: null,
    87→          codAvailable: null,
    88→          returnPolicy: null,
    89→          showWaitlist: false,
    90→          cutoffTime: null,
    91→          daysOfWeek: null,
    92→        }),
    93→        { status: 200, headers: SUCCESS_HEADERS },
    94→      );
    95→    }
    96→
    97→    if (!zipRecord) {
    98→      return new Response(
    99→        JSON.stringify({
   100→          allowed: false,
   101→          message: notFoundMsg,
   102→          notFound: true,
   103→        }),
   104→        { status: 200, headers: SUCCESS_HEADERS },
   105→      );
   106→    }
   107→
   108→    // Inactive zip — treat same as not found regardless of defaultBehavior
   109→    return new Response(
   110→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
   111→      { status: 200, headers: SUCCESS_HEADERS },
   112→    );
   113→  }
   114→
   115→  if (zipRecord.type === "blocked") {
   116→    const errorMsg =
   117→      zipRecord.message ??
   118→      widgetConfig?.errorMessage ??
   119→      "Sorry, we don't deliver to this area yet.";
   120→
   121→    return new Response(
   122→      JSON.stringify({ allowed: false, message: errorMsg }),
   123→      { status: 200, headers: SUCCESS_HEADERS },
   124→    );
   125→  }
   126→
   127→  // Fetch the most relevant active DeliveryRule for this zip.
   128→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
   129→  // Priority 2: rules that match by zone (with no explicit zip list).
   130→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
   131→  const zipCodeUpper = normalizedZip;
   132→  const zipZone = zipRecord.zone ?? null;
   133→
   134→  // Fetch all active rules for the shop ordered by priority so we can apply
   135→  // the matching logic in a single query result.
   136→  const activeRules = await db.deliveryRule.findMany({
   137→    where: { shop, isActive: true },
   138→    orderBy: { priority: "asc" },
   139→  });
   140→
   141→  let matchedRule: (typeof activeRules)[number] | null = null;
   142→
   143→  // Pass 1: explicit zip match — zipCodes field contains this zip code
   144→  for (const rule of activeRules) {
   145→    if (rule.zipCodes) {
   146→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
   147→      if (zips.includes(zipCodeUpper)) {
   148→        matchedRule = rule;
   149→        break;
   150→      }
   151→    }
   152→  }
   153→
   154→  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
   155→  if (!matchedRule && zipZone) {
   156→    for (const rule of activeRules) {
   157→      if (
   158→        rule.zone === zipZone &&
   159→        (!rule.zipCodes || rule.zipCodes.trim() === "")
   160→      ) {
   161→        matchedRule = rule;
   162→        break;
   163→      }
   164→    }
   165→  }
   166→
   167→  // Allowed
   168→  const successMsg =
   169→    zipRecord.message ??
   170→    widgetConfig?.successMessage ??
   171→    "Great news! We deliver to your area.";
   172→
   173→  return new Response(
   174→    JSON.stringify({
   175→      allowed: true,
   176→      message: successMsg,
   177→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
   178→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
   179→      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
   180→      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
   181→      showWaitlist: false,
   182→      cutoffTime: matchedRule?.cutoffTime ?? null,
   183→      daysOfWeek: matchedRule?.daysOfWeek ?? null,
   184→    }),
   185→    { status: 200, headers: SUCCESS_HEADERS },
   186→  );
   187→}
   188→
   189→// Handle GET requests: ?shop=...&zip=...
   190→export const loader = async ({ request }: LoaderFunctionArgs) => {
   191→  const url = new URL(request.url);
   192→
   193→  // Handle CORS preflight
   194→  if (request.method === "OPTIONS") {
   195→    return new Response(null, { status: 204, headers: CORS_HEADERS });
   196→  }
   197→
   198→  const shop = url.searchParams.get("shop");
   199→  const zip = url.searchParams.get("zip");
   200→  return handleZipCheck(shop, zip);
   201→};
   202→
   203→// Handle POST requests with JSON body: { shop, zip }
   204→export const action = async ({ request }: ActionFunctionArgs) => {
   205→  let shop: string | null = null;
   206→  let zip: string | null = null;
   207→
   208→  try {
   209→    const body = await request.json();
   210→    shop = body?.shop ?? null;
   211→    zip = body?.zip ?? null;
   212→  } catch {
   213→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
   214→      status: 400,
   215→      headers: CORS_HEADERS,
   216→    });
   217→  }
   218→
   219→  return handleZipCheck(shop, zip);
   220→};
